function rxQuarter(value){return Math.abs(Number(value)*4-Math.round(Number(value)*4))<1e-8}
function validateRx(v){
  const errors=[],range=(name,label,min,max,quarter=false,required=false)=>{const raw=String(v[name]??'').trim();if(!raw){if(required)errors.push(`${label}: значение обязательно`);return}const n=Number(raw.replace(',','.'));if(!Number.isFinite(n)||n<min||n>max)errors.push(`${label}: допустимый диапазон ${min}…${max}`);else if(quarter&&!rxQuarter(n))errors.push(`${label}: шаг должен быть 0,25`)};
  ['od','os'].forEach(eye=>{const label=eye.toUpperCase();range(`${eye}Sph`,`${label} SPH`,-30,30,true,true);range(`${eye}Cyl`,`${label} CYL`,-12,12,true);range(`${eye}Axis`,`${label} AXIS`,0,180,false,Math.abs(Number(v[`${eye}Cyl`]||0))>0);range(`${eye}Prism`,`${label} Prism`,0,20,true);range(`${eye}Visus`,`${label} Visus`,0,2);if(Number(v[`${eye}Prism`]||0)>0&&!String(v[`${eye}Base`]||'').trim())errors.push(`${label} Base: укажите направление основания призмы`)});
  range('pd','PD',40,80,false,true);range('add','ADD',0,4,true);range('vertex','Вертекс',5,25);
  return errors;
}
