function shiftSummary(shift=state.shift){if(!shift)return {payments:[],parts:[],cash:0,card:0,qr:0,other:0,refunds:0,deposits:0,withdrawals:0,expected:0,turnover:0,movements:[]};const payments=state.payments.filter(x=>x.shiftId===shift.id),parts=payments.filter(x=>x.type!=='Возврат').flatMap(paymentParts),sum=method=>parts.filter(x=>x.method===method).reduce((s,x)=>s+Number(x.amount||0),0),refundOps=payments.filter(x=>x.type==='Возврат'),refunds=refundOps.reduce((s,x)=>s+Number(x.amount||0),0),movements=state.cashMovements.filter(x=>x.shiftId===shift.id),deposits=movements.filter(x=>x.type==='Внесение').reduce((s,x)=>s+Number(x.amount||0),0),withdrawals=movements.filter(x=>x.type==='Изъятие').reduce((s,x)=>s+Number(x.amount||0),0),cash=sum('Наличные'),card=sum('Карта'),qr=sum('QR'),other=sum('Другое'),cashRefunds=refundOps.reduce((sum,refund)=>{const source=state.payments.find(x=>x.id===refund.sourcePaymentId),sourceParts=source?paymentParts(source):[],sourceTotal=sourceParts.reduce((s,x)=>s+Number(x.amount||0),0),cashPart=sourceParts.filter(x=>x.method==='Наличные').reduce((s,x)=>s+Number(x.amount||0),0);return sum+(sourceTotal?Number(refund.amount||0)*cashPart/sourceTotal:(refund.method==='Наличные'?Number(refund.amount||0):0))},0);return {payments,parts,cash,card,qr,other,refunds,deposits,withdrawals,movements,turnover:cash+card+qr+other-refunds,expected:Number(shift.openingBalance||0)+cash-cashRefunds+deposits-withdrawals}}
