function cash(){const shift=state.shift,summary=shiftSummary(),history=state.cashShifts.slice(0,5),operationRows=shift?[...summary.payments.map(x=>({at:x.date,doc:x.orderId?t('cash.order_number',{number:x.orderId}):'—',subject:x.client,type:x.type,method:x.method,amount:(x.type==='Возврат'?-1:1)*Number(x.amount||0)})),...summary.movements.map(x=>({at:window.MedicaI18n.formatDateTime(x.at),doc:x.number,subject:x.reason,type:x.type,method:'Наличные',amount:(x.type==='Изъятие'?-1:1)*Number(x.amount||0)}))]:[];return `<section class="card fiscal-banner"><div><b>${shift?t('cash.shift_number',{number:shift.number}):t('cash.shift_closed')}</b><p>${shift?t('cash.shift_open_summary',{cashier:E(shift.cashier),date:window.MedicaI18n.formatDateTime(shift.openedAt),balance:M(shift.openingBalance)}):t('cash.open_hint')}</p></div><span class="status ${shift?'success':'danger'}">● ${shift?t('cash.active'):t('cash.closed')}</span></section><section class="card"><div class="module-toolbar">${shift?`<button data-cash-deposit>＋ ${t('cash.deposit')}</button><button data-cash-withdraw>− ${t('cash.withdraw')}</button><button class="primary" data-close-shift>${t('cash.close_shift')}</button>`:`<button class="primary" data-open-shift>${t('cash.open_shift')}</button>`}</div></section>${sectionShell([[t('cash.expected'),shift?M(summary.expected):'—',t('cash.expected_hint')],[t('cash.cash_revenue'),shift?M(summary.cash):'—',t('cash.payments')],[t('cash.cashless_revenue'),shift?M(summary.card+summary.qr+summary.other):'—',t('cash.cashless_hint')],[t('cash.mixed'),shift?summary.payments.filter(x=>x.method==='Смешанная').length:'—',t('cash.operations')],[t('cash.refunds'),shift?M(summary.refunds):'—',t('cash.per_shift')],[t('cash.movements'),shift?`${M(summary.deposits)} / ${M(summary.withdrawals)}`:'—',t('cash.movements_hint')]],`<section class="card"><div class="card-title"><div><h2>${t('cash.current_operations')}</h2><p>${t('cash.current_operations_hint')}</p></div></div><div class="table-wrap"><table><thead><tr><th>${t('common.date')}</th><th>${t('cash.document')}</th><th>${t('cash.client_reason')}</th><th>${t('cash.operation')}</th><th>${t('cash.method')}</th><th>${t('common.amount')}</th></tr></thead><tbody>${shift?operationRows.map(x=>`<tr><td>${E(x.at)}</td><td>${E(x.doc)}</td><td>${E(x.subject)}</td><td>${E(cashLabel(x.type))}</td><td>${E(cashLabel(x.method))}</td><td><b>${x.amount<0?'−':''}${M(Math.abs(x.amount))}</b></td></tr>`).join('')||`<tr><td colspan="6">${t('cash.no_operations')}</td></tr>`:`<tr><td colspan="6">${t('cash.shift_closed')}</td></tr>`}</tbody></table></div></section><section class="card"><div class="card-title"><div><h2>${t('cash.closed_history')}</h2></div></div><div class="table-wrap"><table><thead><tr><th>${t('cash.shift')}</th><th>${t('cash.cashier')}</th><th>${t('cash.opened_closed')}</th><th>${t('cash.revenue')}</th><th>${t('cash.expected_short')}</th><th>${t('cash.actual')}</th><th>${t('cash.discrepancy')}</th></tr></thead><tbody>${history.map(x=>`<tr><td>№${x.number}</td><td>${E(x.cashier)}</td><td>${E(window.MedicaI18n.formatDateTime(x.openedAt))}<small>${E(window.MedicaI18n.formatDateTime(x.closedAt))}</small></td><td>${M(x.turnover)}</td><td>${M(x.expectedCash)}</td><td>${M(x.actualCash)}</td><td><b>${x.discrepancy>0?'+':''}${M(x.discrepancy)}</b></td></tr>`).join('')||`<tr><td colspan="7">${t('cash.no_closed_shifts')}</td></tr>`}</tbody></table></div></section>`)}`}
function openCashShift(){if(state.shift)return;flow('Открытие кассовой смены',`${fld('openingBalance','Начальный остаток','number',0,'required min="0"')}${sel('cashier','Кассир',state.employees.filter(x=>/кассир|продавец|управля/i.test(x.role||'')).map(x=>x.name).concat(state.profile.name))}`,v=>{const id=Date.now();state.shift={id,number:Math.max(0,...state.cashShifts.map(x=>Number(x.number)||0))+1,cashier:v.cashier,openedAt:new Date().toISOString(),openingBalance:Number(v.openingBalance),status:'Открыта'};save('shift',state.shift);renderModule();notify(`Кассовая смена №${state.shift.number} открыта`)})}
function cashMovement(type){if(!state.shift){notify('Сначала откройте кассовую смену');return}flow(type,`${fld('amount','Сумма','number','','required min="1"')}${fld('reason','Основание','textarea','','required')}`,v=>{const summary=shiftSummary();if(type==='Изъятие'&&Number(v.amount)>summary.expected){notify('Изъятие превышает ожидаемый наличный остаток');return false}const id=Date.now();state.cashMovements.unshift({id,number:`CS-${String(id).slice(-6)}`,shiftId:state.shift.id,type,amount:Number(v.amount),reason:v.reason,employee:state.profile.name,at:new Date().toISOString()});save('cashMovements',state.cashMovements);renderModule();notify(`${type} сохранено`)})}
function closeCashShift(){if(!state.shift)return;const summary=shiftSummary();flow(`Закрытие смены №${state.shift.number}`,`${fld('actualCash','Фактическая наличность','number',summary.expected,'required min="0"')}${fld('comment','Комментарий к закрытию','textarea','')}`,v=>{const actual=Number(v.actualCash),closed={...state.shift,closedAt:new Date().toISOString(),status:'Закрыта',cash:summary.cash,nonCash:summary.card+summary.qr+summary.other,mixed:summary.payments.filter(x=>x.method==='Смешанная').length,refunds:summary.refunds,deposits:summary.deposits,withdrawals:summary.withdrawals,turnover:summary.turnover,expectedCash:summary.expected,actualCash:actual,discrepancy:actual-summary.expected,comment:v.comment};if(closed.discrepancy!==0&&!v.comment.trim()){notify('При расхождении обязателен комментарий');return false}state.cashShifts.unshift(closed);save('cashShifts',state.cashShifts);state.shift=false;save('shift',false);renderModule();notify(`Смена №${closed.number} закрыта · расхождение ${M(closed.discrepancy)}`)})}
function serials(){const activeKits=state.kits.filter(x=>x.status==='Собран');return sectionShell([['Единиц',state.serialUnits.length,'серийный учёт'],['В резерве',state.serialUnits.filter(x=>x.status==='В резерве').length,'под заказы'],['Продано',state.serialUnits.filter(x=>x.status==='Продан').length,'единиц'],['Комплекты',activeKits.length,'собрано']],`<section class="card"><div class="module-toolbar"><button class="primary" data-kit>Собрать комплект</button></div><div class="table-wrap"><table><thead><tr><th>Серия / штрихкод</th><th>Изделие</th><th>Локация</th><th>Статус</th><th>Клиент / заказ</th><th></th></tr></thead><tbody>${state.serialUnits.map(x=>`<tr><td><b>${E(x.serial)}</b><small>${E(x.barcode||'—')}</small></td><td>${E(x.product)}</td><td>${E(x.location)}</td><td>${E(x.status)}</td><td>${E(x.client)}${x.orderId?`<small>Заказ №${x.orderId}</small>`:''}</td><td class="row-actions"><button data-serial="${x.id}">История</button>${x.kitId?`<button data-kit-passport="${x.kitId}">Паспорт</button><button data-disassemble-kit="${x.kitId}" ${x.status==='Разобран'?'disabled':''}>Разобрать</button>`:`<button data-serial-op="${x.id}">Операция</button>`}</td></tr>`).join('')}</tbody></table></div></section>`)}
function equipment(){return sectionShell([['На балансе',state.equipment.length,'единицы'],['Работает',state.equipment.filter(x=>x.status==='Работает').length,'доступно'],['На ТО',state.equipment.filter(x=>x.status==='На ТО').length,'обслуживание'],['В ремонте',state.equipment.filter(x=>x.status==='Ремонт').length,'недоступно']],`<section class="card"><div class="module-toolbar"><button class="primary" data-new-eq>＋ Оборудование</button></div><div class="table-wrap"><table><thead><tr><th>№ / серия</th><th>Оборудование</th><th>Локация</th><th>Состояние</th><th>Следующее ТО</th><th>Обследования</th><th></th></tr></thead><tbody>${state.equipment.map(x=>`<tr><td><b>${x.number}</b><small>${x.serial}</small></td><td>${E(x.name)}</td><td>${E(x.location)}</td><td>${E(x.status)}</td><td>${E(x.nextService)}</td><td>${E(x.exams||'—')}</td><td><button data-edit-eq="${x.id}">Изменить</button></td></tr>`).join('')}</tbody></table></div></section>`)}
