const PROCUREMENT_STATUSES=['Черновик','Отправлено','Подтверждено','Частично поставлено','В пути','Получено','Отменено'];
function procurementTotal(p){return (p.items||[]).reduce((s,x)=>s+Number(x.qty||0)*Number(x.price||0),0)}
function procurementProgress(p){const ordered=(p.items||[]).reduce((s,x)=>s+Number(x.qty||0),0),received=(p.items||[]).reduce((s,x)=>s+Number(x.receivedQty||0),0);return {ordered,received,percent:ordered?Math.round(received/ordered*100):0}}
function procurementsView(){return sectionShell([['Закупок',state.procurements.length,'в журнале'],['В пути',state.procurements.filter(x=>x.status==='В пути').length,'поставок'],['Частично',state.procurements.filter(x=>x.status==='Частично поставлено').length,'поставлено'],['Получено',state.procurements.filter(x=>x.status==='Получено').length,'закрыто']],`<section class="card"><div class="module-toolbar"><label class="search">⌕ <input data-live placeholder="Номер, поставщик, товар или заказ"></label><button class="primary" data-new-procurement>＋ Новая закупка</button></div><div class="table-wrap"><table><thead><tr><th>Закупка</th><th>Поставщик</th><th>Позиции</th><th>Склад / срок</th><th>Сумма</th><th>Статус</th><th></th></tr></thead><tbody>${state.procurements.map(p=>{const progress=procurementProgress(p);return `<tr><td><b>${E(p.number)}</b><small>${p.orderId?`Заказ №${p.orderId}`:'Без заказа'}</small></td><td>${E(p.supplier)}</td><td>${E((p.items||[]).map(x=>`${x.name} × ${x.qty}`).join(', '))}<small>Получено ${progress.received} из ${progress.ordered}</small></td><td>${E(p.warehouse)}<small>${E(p.eta||'Срок не указан')}</small></td><td><b>${M(procurementTotal(p))}</b><small>${E(p.currency)}</small></td><td><span class="status info">${E(p.status)}</span></td><td class="row-actions"><button data-procurement-detail="${p.id}">Карточка</button><button data-procurement-status="${p.id}" ${['Получено','Отменено'].includes(p.status)?'disabled':''}>Статус</button><button data-receive-procurement="${p.id}" ${['Черновик','Получено','Отменено'].includes(p.status)?'disabled':''}>Принять</button></td></tr>`}).join('')}</tbody></table></div></section>`)}
function receiptsView(){const receipts=state.invoices.filter(x=>x.procurementId||x.type==='Приход');return sectionShell([['Приходных',receipts.length,'документов'],['Проведено',receipts.filter(x=>x.status==='Проведена').length,'накладных'],['Позиций',receipts.reduce((s,x)=>s+(x.items?.length||0),0),'принято'],['Закупок закрыто',state.procurements.filter(x=>x.status==='Получено').length,'получено']],`<section class="card"><div class="module-toolbar"><label class="search">⌕ <input data-live placeholder="Номер, поставщик, склад или закупка"></label></div><div class="table-wrap"><table><thead><tr><th>Документ</th><th>Основание</th><th>Поставщик</th><th>Склад</th><th>Позиции</th><th>Ответственный</th><th>Статус</th></tr></thead><tbody>${receipts.map(x=>`<tr><td><b>${E(x.name)}</b><small>${E(x.createdAt||'—')}</small></td><td>${x.procurementId?`Закупка №${x.procurementId}`:E(x.type)}</td><td>${E(x.supplier||x.from||'—')}</td><td>${E(x.warehouse||'—')}</td><td>${E(x.items?.map(i=>`${i.name} × ${i.qty}`).join(', ')||x.amount)}</td><td>${E(x.responsible||'—')}</td><td>${E(x.status)}</td></tr>`).join('')}</tbody></table></div></section>`)}
function procurementLine(index,seed={},required=false){return `<div class="procurement-form-line full"><span class="procurement-line-number">${index}</span><label class="procurement-product">Товар<select name="product${index}" ${required?'required':''}><option value="">Выберите товар</option>${state.catalog.map(x=>`<option value="${x.id}" ${x.id==seed.productId?'selected':''}>${E(x.name)} · ${E(x.sku)}</option>`).join('')}</select></label><label>Количество<input name="qty${index}" type="number" min="1" step="1" value="${index===1?Number(seed.qty||1):1}" ${required?'required':''}></label><label>Цена за единицу<input name="price${index}" type="number" min="0" step="1" value="${index===1&&seed.price!=null?Number(seed.price):''}" placeholder="0" ${required?'required':''}></label><output data-procurement-line-total>${M(0)}</output></div>`}
function createProcurementFull(seed={}){const supplierOptions=state.suppliers.filter(x=>x.status!=='Приостановлен').map(x=>x.name),employees=state.employees.map(x=>x.name),seedItems=seed.items?.length?seed.items:[seed],lineCount=Math.max(3,seedItems.length);flow('Новая закупка',`${sel('supplier','Поставщик',supplierOptions,seed.supplier)}${sel('currency','Валюта',['UZS','USD','EUR'],seed.currency||'UZS')}${fld('eta','Ожидаемая дата','date',seed.eta,'required')}${sel('warehouse','Склад назначения',['Центральный склад','Медцентр Юнусабад','Магазин Чиланзар','Медцентр Самарканд'],seed.warehouse)}${linkedSelect('orderId','Связанный заказ',state.orders,seed.orderId,x=>`№${x.id} · ${x.client} · ${x.product}`)}${sel('responsible','Ответственный',employees,seed.responsible)}${fld('comment','Комментарий','textarea',seed.comment)}<div class="procurement-lines-title full"><div><h3>Позиции закупки</h3><p>Каждый товар, количество и цена собраны в одной строке.</p></div><strong data-procurement-total>${M(0)}</strong></div>${Array.from({length:lineCount},(_,i)=>procurementLine(i+1,seedItems[i]||{},i===0)).join('')}`,v=>{const items=Array.from({length:lineCount},(_,i)=>i+1).filter(i=>v[`product${i}`]).map(i=>{const p=state.catalog.find(x=>x.id==v[`product${i}`]);return {productId:p.id,name:p.name,qty:Number(v[`qty${i}`]||1),receivedQty:0,price:Number(v[`price${i}`]||0)}});if(!items.length){notify('Добавьте хотя бы одну позицию закупки');return false}const id=Date.now(),p={id,number:`PO-${String(id).slice(-6)}`,supplier:v.supplier,currency:v.currency,eta:v.eta,warehouse:v.warehouse,orderId:v.orderId?+v.orderId:null,responsible:v.responsible,comment:v.comment,items,status:'Черновик',history:[{at:new Date().toISOString(),status:'Черновик',note:'Закупка создана'}]};state.procurements.unshift(p);put('procurements');renderModule();notify(`Закупка ${p.number} сохранена как черновик`)});const form=$('#entityForm'),update=()=>{let total=0;$$('.procurement-form-line',form).forEach(line=>{const qty=Number($('[name^="qty"]',line)?.value||0),price=Number($('[name^="price"]',line)?.value||0),sum=qty*price;line.querySelector('output').textContent=M(sum);total+=sum});$('[data-procurement-total]',form).textContent=M(total)};form.addEventListener('input',update);form.addEventListener('change',update);update()}
function procurementDetail(id){const p=state.procurements.find(x=>x.id===+id),progress=procurementProgress(p);$('#detailTitle').textContent=p.number;$('#detailContent').innerHTML=`<div class="detail-list">${[['Поставщик',p.supplier],['Статус',p.status],['Ожидаемая дата',p.eta||'—'],['Склад',p.warehouse],['Ответственный',p.responsible],['Связанный заказ',p.orderId?`№${p.orderId}`:'—'],['Валюта',p.currency],['Сумма',M(procurementTotal(p))],['Получено',`${progress.received} из ${progress.ordered}`],['Комментарий',p.comment||'—']].map(x=>`<div><small>${x[0]}</small><strong>${E(x[1])}</strong></div>`).join('')}</div><div class="order-lines">${p.items.map(x=>`<div class="order-line"><span><b>${E(x.name)}</b><small>Заказано ${x.qty} · получено ${x.receivedQty||0}</small></span><b>${M(x.qty*x.price)}</b></div>`).join('')}</div>${timeline(p.history.map(x=>[window.MedicaI18n.formatDateTime(x.at),x.status,x.note||'']))}`;detailDialog.showModal()}
